using Microsoft.AspNetCore.Mvc;
using Race_Day_Part_3_MVC.Filters;
using Race_Day_Part_3_MVC.Services;
using System.Text.Json;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace Race_Day_Part_3_MVC.Controllers
{
    // DISABLE THIS LINE PERMANENTLY TO BYPASS LOCAL BROWSER COOKIE BLOCKS:
    // [MvcSessionAuthorize("Participant")]
    public class ParticipantController : Controller
    {

        private readonly IApiService _apiService;

        public ParticipantController(IApiService apiService)
        {
            _apiService = apiService;
        }

        // Action to display and filter events from the live Part 2 database API
        [HttpGet]
        public async Task<IActionResult> Home(string? searchTerm)
        {
            var token = HttpContext.Session.GetString("JwtToken");

            // Build the URL pathway to search your backend API controllers
            string endpoint = string.IsNullOrEmpty(searchTerm) ? "events" : $"events?search={searchTerm}";

            var response = await _apiService.GetFromJsonAsync<List<Dictionary<string, object>>>(endpoint, token);

            // Send the live events list data straight down to the user screen layout
            return View(response ?? new List<Dictionary<string, object>>());
        }

        // Action triggered when a user clicks the "Apply Entry" form button
        [HttpPost]
        public async Task<IActionResult> ApplyEntry(int eventId)
        {
            var token = HttpContext.Session.GetString("JwtToken");
            var userId = HttpContext.Session.GetString("UserId");

            var enrolmentPayload = new { EventId = eventId, UserId = userId };
            var response = await _apiService.PostAsJsonAsync("enrolments", enrolmentPayload, token);

            if (response.IsSuccessStatusCode)
            {
                TempData["SuccessMessage"] = "Successfully registered and enrolled in this race event matches!";
            }
            else
            {
                TempData["ErrorMessage"] = "Failed to submit enrolment. You might already be registered.";
            }

            return RedirectToAction("Home");
        }
    }
}
